1	"use client";
2	
3	import { useActionState, useEffect, useRef, useState } from "react";
4	import Link from "next/link";
5	import { purchaseDomain } from "@/lib/actions-domains";
6	import { DOMAIN_TERMS, domainTermPriceCents } from "@/lib/billing-terms";
7	import { fmtMoney } from "@/components/ui/primitives";
8	import type { DomainCheckResult } from "@/components/customer/DomainSearch";
9	import { PhoneCountryInput } from "@/components/customer/PhoneCountryInput";
10	import { AddressAutocompleteInput, type AddressSuggestion } from "@/components/customer/AddressAutocompleteInput";
11	import { PaymentStep } from "@/components/customer/PaymentStep";
12	import { walletSplit } from "@/lib/wallet-split";
13	
14	const DOMAIN_RE = /^[a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?\.[a-z]{2,24}$/;
15	// Same shape lib/domain-inbox-email.ts and lib/actions-email-hosting.ts's
16	// addMailbox() validate server-side — checked here only for immediate
17	// feedback; the server is the real gate.
18	const LOCAL_PART_RE = /^[a-z0-9]+(?:[._-][a-z0-9]+)*$/;
19	
20	const COUNTRIES: [string, string][] = [
21	  ["US", "United States"],
22	  ["CA", "Canada"],
23	  ["GB", "United Kingdom"],
24	  ["IE", "Ireland"],
25	  ["DE", "Germany"],
26	  ["FR", "France"],
27	  ["NL", "Netherlands"],
28	  ["BE", "Belgium"],
29	  ["ES", "Spain"],
30	  ["IT", "Italy"],
31	  ["PT", "Portugal"],
32	  ["SE", "Sweden"],
33	  ["NO", "Norway"],
34	  ["DK", "Denmark"],
35	  ["FI", "Finland"],
36	  ["PL", "Poland"],
37	  ["CH", "Switzerland"],
38	  ["AT", "Austria"],
39	  ["AU", "Australia"],
40	  ["NZ", "New Zealand"],
41	  ["JP", "Japan"],
42	  ["SG", "Singapore"],
43	  ["IN", "India"],
44	  ["BR", "Brazil"],
45	  ["MX", "Mexico"],
46	  ["ZA", "South Africa"],
47	];
48	
49	const BASE_STEPS = ["Domain", "Term", "Contact"] as const;
50	
51	type Contact = {
52	  firstName: string;
53	  lastName: string;
54	  address1: string;
55	  city: string;
56	  stateProvince: string;
57	  postalCode: string;
58	  country: string;
59	  phone: string;
60	  email: string;
61	};
62	
63	function Stepper({ step, steps }: { step: number; steps: readonly string[] }) {
64	  return (
65	    <div className="mb-6 flex flex-wrap items-center gap-2 text-xs">
66	      {steps.map((s, i) => (
67	        <div key={s} className="flex items-center gap-2">
68	          <span
69	            className={`flex h-6 w-6 items-center justify-center rounded-full border text-[11px] font-semibold transition-colors ${
70	              i === step
71	                ? "border-brand-400 bg-brand-500/20 text-brand-200"
72	                : i < step
73	                  ? "border-emerald-500/40 bg-emerald-500/15 text-emerald-300"
74	                  : "border-white/10 text-slate-500"
75	            }`}
76	          >
77	            {i < step ? "✓" : i + 1}
78	          </span>
79	          <span className={i === step ? "text-white" : "text-slate-500"}>{s}</span>
80	          {i < steps.length - 1 && <span className="mx-1 text-slate-700">→</span>}
81	        </div>
82	      ))}
83	    </div>
84	  );
85	}
86	
87	export function DomainRegisterWizard({
88	  initialDomain,
89	  initialCheck,
90	  defaultEmail,
91	  balanceCents,
92	  freeInboxPlan,
93	  geoapifyEnabled,
94	}: {
95	  initialDomain: string;
96	  initialCheck: DomainCheckResult | null;
97	  defaultEmail: string;
98	  balanceCents: number;
99	  /** The real "Free Domain Inbox" plan (lib/domain-inbox-email.ts), or null if
100	   *  it hasn't been seeded on this environment yet — the Email step only
101	   *  renders when this is present, so the wizard never claims a feature that
102	   *  isn't actually there. */
103	  freeInboxPlan: { mailboxes: number; storageGB: number } | null;
104	  /** Whether GEOAPIFY_API_KEY is set on this environment (lib/geoapify.ts). When
105	   *  false the Street address field stays a plain text input, exactly as it was
106	   *  before this feature existed — same "don't claim a feature that isn't
107	   *  provisioned" rule the Email step's `freeInboxPlan` follows. */
108	  geoapifyEnabled: boolean;
109	}) {
110	  const [state, action, pending] = useActionState(
111	    purchaseDomain,
112	    {} as { error?: string; checkout?: { clientSecret: string; publishableKey: string } },
113	  );
114	  const formRef = useRef<HTMLFormElement>(null);
115	
116	  // The embedded card-payment step (Part 3): purchaseDomain returns `{checkout}`
117	  // instead of redirecting when the wallet can't cover the total (cardCents > 0
118	  // below). Same shape as payAndDeploy/PaymentStep (lib/actions.ts,
119	  // components/customer/DeployWizard.tsx) — the SAME form/action is resubmitted
120	  // to request a session, never a second server action.
121	  const [checkoutSession, setCheckoutSession] = useState<{ clientSecret: string; publishableKey: string } | null>(
122	    null,
123	  );
124	  const [stripePhase, setStripePhase] = useState<"idle" | "loading" | "error">("idle");
125	  useEffect(() => {
126	    if (state?.checkout) {
127	      setCheckoutSession(state.checkout);
128	      setStripePhase("idle");
129	    } else if (state?.error) {
130	      setCheckoutSession(null);
131	      setStripePhase("error");
132	    }
133	  }, [state]);
134	  function requestStripeSession() {
135	    setStripePhase("loading");
136	    formRef.current?.requestSubmit();
137	  }
138	
139	  const STEPS = freeInboxPlan ? ([...BASE_STEPS, "Email", "Review"] as const) : ([...BASE_STEPS, "Review"] as const);
140	  const EMAIL_STEP = freeInboxPlan ? BASE_STEPS.length : -1;
141	  const REVIEW_STEP = STEPS.length - 1;
142	
143	  const [step, setStep] = useState(0);
144	  const [domain, setDomain] = useState(initialDomain);
145	  const [check, setCheck] = useState<DomainCheckResult | null>(initialCheck);
146	  const [checking, setChecking] = useState(false);
147	  const [checkError, setCheckError] = useState<string | null>(null);
148	  const [years, setYears] = useState(1);
149	  const [mailboxLocal, setMailboxLocal] = useState("");
150	
151	  const [contact, setContact] = useState<Contact>({
152	    firstName: "",
153	    lastName: "",
154	    address1: "",
155	    city: "",
156	    stateProvince: "",
157	    postalCode: "",
158	    country: "US",
159	    phone: "",
160	    email: defaultEmail,
161	  });
162	  // Real per-country validity from PhoneCountryInput (libphonenumber-js), not
163	  // just PHONE_RE's shape match — a shape-valid "+1.0000000000" is still not a
164	  // real number.
165	  const [phoneValid, setPhoneValid] = useState(false);
166	  // Best-effort Geoapify confidence check on the manually-typed address case
167	  // (someone who ignores the autocomplete dropdown and just types). Advisory
168	  // only — ICANN registrant-contact fields are the source of truth, not
169	  // Geoapify's, so this never blocks continuing, only flags a possible typo.
170	  const [addressWarning, setAddressWarning] = useState<string | null>(null);
171	  const [addressChecking, setAddressChecking] = useState(false);
172	
173	  // Live search for changing the domain in step 1.
174	  const [q, setQ] = useState("");
175	  const [results, setResults] = useState<DomainCheckResult[] | null>(null);
176	  const [searching, setSearching] = useState(false);
177	  const timer = useRef<ReturnType<typeof setTimeout> | null>(null);
178	
179	  useEffect(() => {
180	    if (timer.current) clearTimeout(timer.current);
181	    const query = q.trim().toLowerCase();
182	    if (query.length < 2) {
183	      setResults(null);
184	      setSearching(false);
185	      return;
186	    }
187	    setSearching(true);
188	    timer.current = setTimeout(async () => {
189	      try {
190	        const res = await fetch(`/api/domains/check?q=${encodeURIComponent(query)}`, { cache: "no-store" });
191	        const json: { results?: DomainCheckResult[] } = await res.json();
192	        setResults(json.results ?? []);
193	      } catch {
194	        setResults([]);
195	      }
196	      setSearching(false);
197	    }, 400);
198	    return () => {
199	      if (timer.current) clearTimeout(timer.current);
200	    };
201	  }, [q]);
202	
203	  // Light confidence check on the manually-typed address case — Geoapify's own
204	  // match confidence on the FULL address string, advisory only (see the
205	  // addressWarning state doc above). Skipped entirely when Geoapify isn't
206	  // configured, and never fires until every field a real address needs is
207	  // present (no point flagging a still-half-typed form).
208	  const addressTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
209	  useEffect(() => {
210	    if (addressTimer.current) clearTimeout(addressTimer.current);
211	    if (!geoapifyEnabled) return;
212	    // Deliberately excludes contact.country: it's a bare ISO-3166 alpha-2 code
213	    // (e.g. "CA"), and appending that as literal free-text confused Geoapify's
214	    // geocoder into a false-negative — a real, verifiable Canadian address
215	    // (confidence 1.0 without it) returned ZERO results with "CA" tacked on,
216	    // because Geoapify read it as the "California" abbreviation rather than a
217	    // country code. The country is already passed correctly via the `country`
218	    // bias param below — it doesn't belong in the query text too.
219	    const full = [contact.address1, contact.city, contact.stateProvince, contact.postalCode]
220	      .map((s) => s.trim())
221	      .filter(Boolean)
222	      .join(", ");
223	    if (!contact.address1.trim() || !contact.city.trim() || !contact.postalCode.trim()) {
224	      setAddressWarning(null);
225	      return;
226	    }
227	    setAddressChecking(true);
228	    addressTimer.current = setTimeout(async () => {
229	      try {
230	        const params = new URLSearchParams({ q: full, country: contact.country });
231	        const res = await fetch(`/api/geoapify/autocomplete?${params.toString()}`, { cache: "no-store" });
232	        const json: { results?: { confidence: number }[] } = await res.json();
233	        const top = json.results?.[0];
234	        setAddressWarning(
235	          !top || top.confidence < 0.5 ? "We couldn't verify this address — check for typos." : null,
236	        );
237	      } catch {
238	        // Best-effort — a Geoapify hiccup must never block or scare the customer.
239	        setAddressWarning(null);
240	      }
241	      setAddressChecking(false);
242	    }, 900);
243	    return () => {
244	      if (addressTimer.current) clearTimeout(addressTimer.current);
245	    };
246	    // eslint-disable-next-line react-hooks/exhaustive-deps
247	  }, [geoapifyEnabled, contact.address1, contact.city, contact.stateProvince, contact.postalCode, contact.country]);
248	
249	  async function recheck(name: string) {
250	    setChecking(true);
251	    setCheckError(null);
252	    try {
253	      const res = await fetch(`/api/domains/check?q=${encodeURIComponent(name)}`, { cache: "no-store" });
254	      const json: { results?: DomainCheckResult[]; error?: string } = await res.json();
255	      const match = (json.results ?? []).find((r) => r.domain === name) ?? null;
256	      setCheck(match);
257	      if (json.error) setCheckError(json.error);
258	      else if (!match) setCheckError("Could not check that domain — try another.");
259	    } catch {
260	      setCheckError("Availability check failed — try again.");
261	      setCheck(null);
262	    }
263	    setChecking(false);
264	  }
265	
266	  function pickDomain(r: DomainCheckResult) {
267	    setDomain(r.domain);
268	    setCheck(r);
269	    setCheckError(null);
270	    setQ("");
271	    setResults(null);
272	  }
273	
274	  const priceCents = check?.priceCents ?? null;
275	  const renewCents = check?.renewCents ?? null;
276	  const domainOk =
277	    DOMAIN_RE.test(domain) && !!check && check.available && !check.premium && priceCents !== null;
278	  const totalCents = priceCents !== null ? domainTermPriceCents(priceCents, years) : 0;
279	  const afterCents = balanceCents - totalCents;
280	  // Whether to apply wallet balance at all — defaults OFF (owner's explicit
281	  // choice for this wizard: registering a domain shouldn't silently reach
282	  // into the wallet unless the customer opts in), unlike DeployWizard.tsx's
283	  // default-on. A customer can still turn it on to draw from the wallet, or
284	  // leave it off to pay entirely by card. Real gap found live: this wizard
285	  // previously hardcoded useWallet to true with no toggle at all, so
286	  // wallet-covers-it silently auto-debited with no way to choose card
287	  // instead — the ONLY payment method a customer ever saw was whichever this
288	  // hardcoded flag picked for them.
289	  const [useWallet, setUseWallet] = useState(false);
290	  // The card leg — the shortfall a card must cover once the wallet is applied.
291	  // Zero means the wallet alone covers it. The SAME `walletSplit` the server
292	  // action uses (lib/wallet-split.ts is dependency-free specifically so both
293	  // sides share it) — a naive `totalCents - balanceCents` can land a 1–49c
294	  // remainder that Stripe rejects, and computing it differently here than the
295	  // server does would show this Payment step when the server would actually
296	  // take the direct-wallet path (or vice versa).
297	  const { cardCents, walletApplied } = walletSplit({ dueCents: totalCents, balanceCents, useWallet });
298	
299	  // If the price changes after a Stripe session was already opened (a live
300	  // re-check moved the price, or the term changed), drop the stale session so
301	  // PaymentStep asks for a fresh one — never lets a customer confirm a card
302	  // charge against a total that no longer matches what's on screen (the same
303	  // staleness guard components/customer/DeployWizard.tsx applies).
304	  const prevCardCentsRef = useRef(cardCents);
305	  useEffect(() => {
306	    if (checkoutSession && prevCardCentsRef.current !== cardCents) {
307	      setCheckoutSession(null);
308	      setStripePhase("idle");
309	    }
310	    prevCardCentsRef.current = cardCents;
311	  }, [cardCents, checkoutSession]);
312	
313	  const contactValid =
314	    contact.firstName.trim().length > 0 &&
315	    contact.lastName.trim().length > 0 &&
316	    contact.address1.trim().length > 0 &&
317	    contact.city.trim().length > 0 &&
318	    contact.stateProvince.trim().length > 0 &&
319	    contact.postalCode.trim().length > 0 &&
320	    contact.country.length === 2 &&
321	    phoneValid &&
322	    /^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(contact.email);
323	
324	  const term = DOMAIN_TERMS.find((t) => t.years === years) ?? DOMAIN_TERMS[0];
325	  const mailboxLocalTrim = mailboxLocal.trim().toLowerCase();
326	  const mailboxLocalValid = mailboxLocalTrim.length === 0 || (LOCAL_PART_RE.test(mailboxLocalTrim) && mailboxLocalTrim.length <= 64);
327	  // The Email step is always passable without input — the free inbox is
328	  // reserved either way, an address is optional (see lib/domain-inbox-email.ts).
329	  const canContinue =
330	    (step === 0 && domainOk) ||
331	    step === 1 ||
332	    (step === 2 && contactValid) ||
333	    (EMAIL_STEP >= 0 && step === EMAIL_STEP && mailboxLocalValid) ||
334	    step === REVIEW_STEP;
335	  const isLast = step === REVIEW_STEP;
336	
337	  const set = (k: keyof Contact) => (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) =>
338	    setContact((c) => ({ ...c, [k]: e.target.value }));
339	
340	  return (
341	    <div className={`grid gap-6 ${step === REVIEW_STEP ? "" : "lg:grid-cols-[1fr_320px]"}`}>
342	      <form ref={formRef} action={action} className="card">
343	        {/* hidden fields submitted to purchaseDomain */}
344	        <input type="hidden" name="domain" value={domain} />
345	        <input type="hidden" name="years" value={years} />
346	        <input type="hidden" name="firstName" value={contact.firstName} />
347	        <input type="hidden" name="lastName" value={contact.lastName} />
348	        <input type="hidden" name="address1" value={contact.address1} />
349	        <input type="hidden" name="city" value={contact.city} />
350	        <input type="hidden" name="stateProvince" value={contact.stateProvince} />
351	        <input type="hidden" name="postalCode" value={contact.postalCode} />
352	        <input type="hidden" name="country" value={contact.country} />
353	        <input type="hidden" name="phone" value={contact.phone} />
354	        <input type="hidden" name="email" value={contact.email} />
355	        <input type="hidden" name="mailboxLocalPart" value={mailboxLocalTrim} />
356	        <input type="hidden" name="useWallet" value={useWallet ? "1" : "0"} />
357	
358	        <Stepper step={step} steps={STEPS} />
359	
360	        {state?.error && (
361	          <div className="mb-4 rounded-xl border border-red-500/30 bg-red-500/10 px-3 py-2 text-sm text-red-300">
362	            {state.error}
363	          </div>
364	        )}
365	
366	        {/* STEP 1 — DOMAIN */}
367	        {step === 0 && (
368	          <div>
369	            <h2 className="mb-1 font-semibold">Confirm your domain</h2>
370	            <p className="mb-4 text-sm text-slate-400">
371	              We&apos;ll re-check availability and pricing live before you commit.
372	            </p>
373	
374	            <div
375	              className={`rounded-xl border p-4 ${
376	                domainOk
377	                  ? "border-emerald-500/30 bg-emerald-500/[0.06]"
378	                  : check && (check.premium || !check.available)
379	                    ? "border-amber-500/30 bg-amber-500/[0.06]"
380	                    : "border-white/10 bg-white/[0.02]"
381	              }`}
382	            >
383	              <div className="flex flex-wrap items-center justify-between gap-3">
384	                <span className="font-mono text-base font-semibold">{domain || "no domain selected"}</span>
385	                {checking ? (
386	                  <span className="flex items-center gap-2 text-xs text-slate-400">
387	                    <span className="block h-3.5 w-3.5 animate-spin rounded-full border-2 border-slate-500 border-t-brand-400" />
388	                    checking…
389	                  </span>
390	                ) : domainOk && priceCents !== null ? (
391	                  <span className="text-sm font-semibold text-emerald-400">
392	                    available · {fmtMoney(priceCents)}
393	                    <span className="text-xs font-normal text-slate-400">/yr</span>
394	                  </span>
395	                ) : check?.premium ? (
396	                  <span className="text-sm font-semibold text-amber-300">premium — not supported</span>
397	                ) : check && !check.available ? (
398	                  <span className="text-sm font-semibold text-amber-300">taken</span>
399	                ) : (
400	                  <span className="text-sm text-slate-500">not checked</span>
401	                )}
402	              </div>
403	              {check?.renewCents != null && domainOk && (
404	                <p className="mt-2 text-xs text-slate-500">
405	                  Renews at {fmtMoney(check.renewCents)}/yr after the initial term.
406	                </p>
407	              )}
408	              <button
409	                type="button"
410	                onClick={() => domain && recheck(domain)}
411	                disabled={!DOMAIN_RE.test(domain) || checking}
412	                className="btn-ghost mt-2 px-0 text-xs"
413	              >
414	                ↻ Re-check availability
415	              </button>
416	            </div>
417	
418	            {checkError && <p className="mt-3 text-sm text-amber-300">{checkError}</p>}
419	
420	            <div className="mt-5">
421	              <label className="label">Search for a different domain</label>
422	              <div className="relative max-w-md">
423	                <input
424	                  className="input pr-10"
425	                  placeholder="another-name.com"
426	                  value={q}
427	                  onChange={(e) => setQ(e.target.value)}
428	                  autoComplete="off"
429	                  spellCheck={false}
430	                />
431	                <span className="absolute right-3.5 top-1/2 -translate-y-1/2 text-slate-500">
432	                  {searching ? (
433	                    <span className="block h-4 w-4 animate-spin rounded-full border-2 border-slate-500 border-t-brand-400" />
434	                  ) : (
435	                    <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
436	                      <circle cx="11" cy="11" r="7" />
437	                      <path d="m20 20-3.5-3.5" />
438	                    </svg>
439	                  )}
440	                </span>
441	              </div>
442	
443	              {results !== null && !searching && (
444	                <ul className="mt-3 max-w-md divide-y divide-white/[0.05] overflow-hidden rounded-xl border border-white/[0.06] bg-navy-900/60">
445	                  {results.length === 0 && (
446	                    <li className="px-4 py-3 text-sm text-slate-400">No supported TLDs match that search.</li>
447	                  )}
448	                  {results.map((r) => (
449	                    <li key={r.domain} className="flex items-center justify-between gap-3 px-4 py-2.5">
450	                      <span className="font-mono text-sm">{r.domain}</span>
451	                      {r.available && !r.premium && r.priceCents !== null ? (
452	                        <span className="flex items-center gap-3">
453	                          <span className="text-sm font-semibold text-emerald-400">{fmtMoney(r.priceCents)}</span>
454	                          <button
455	                            type="button"
456	                            onClick={() => pickDomain(r)}
457	                            className="btn-secondary px-3 py-1 text-xs"
458	                          >
459	                            Choose
460	                          </button>
461	                        </span>
462	                      ) : r.premium ? (
463	                        <span className="text-xs text-amber-300">premium</span>
464	                      ) : (
465	                        <span className="text-xs text-slate-500">taken</span>
466	                      )}
467	                    </li>
468	                  ))}
469	                </ul>
470	              )}
471	            </div>
472	          </div>
473	        )}
474	
475	        {/* STEP 2 — TERM */}
476	        {step === 1 && (
477	          <div>
478	            <h2 className="mb-1 font-semibold">Choose your registration term</h2>
479	            <p className="mb-4 text-sm text-slate-400">Commit longer, save more — WHOIS privacy is always included.</p>
480	            <div className="grid gap-3 sm:grid-cols-3">
481	              {DOMAIN_TERMS.map((t) => {
482	                const total = priceCents !== null ? domainTermPriceCents(priceCents, t.years) : 0;
483	                const perYear = t.years > 0 ? Math.round(total / t.years) : total;
484	                const on = years === t.years;
485	                return (
486	                  <button
487	                    type="button"
488	                    key={t.years}
489	                    onClick={() => setYears(t.years)}
490	                    className={`card relative p-4 text-left transition ${
491	                      on ? "!border-brand-400 ring-1 ring-brand-400" : "hover:border-white/20"
492	                    }`}
493	                  >
494	                    {t.discountPct > 0 && (
495	                      <span className="absolute right-2 top-2 rounded-full bg-emerald-500/20 px-1.5 py-0.5 text-[10px] font-semibold text-emerald-300">
496	                        −{t.discountPct}%
497	                      </span>
498	                    )}
499	                    <p className="text-sm font-semibold">{t.label}</p>
500	                    <p className="mt-1 text-xl font-bold">
501	                      {fmtMoney(perYear)}
502	                      <span className="text-xs font-normal text-slate-400">/yr</span>
503	                    </p>
504	                    <p className="mt-0.5 text-[11px] text-slate-500">
505	                      {fmtMoney(total)} total{t.discountPct > 0 ? ` · save ${t.discountPct}%` : ""}
506	                    </p>
507	                  </button>
508	                );
